// Candidature d'exemple pour la recette (Lancement manuel WF1). Lien fictif : à supprimer du Sheet après un test en mode réel.
return [{ json: { body: {
  lien_offre: 'https://exemple.invalid/offre-test-candidatures-suivi',
  statut: 'En attente',
  entreprise: 'ZZ Test',
  poste: 'Poste de test',
  notes: 'Ligne de recette : à supprimer.',
} } }];

// MODE        : 'simulation' = tout est calculé et renvoyé, RIEN n'est écrit dans le Sheet.
//               'reel'       = la ligne est ajoutée ou mise à jour. Bascule sur décision explicite, après la recette.
// SHEET_ID    : identifiant du Google Sheet « Suivi des candidatures » (Drive, dossier Job Search).
// ONGLET_GID  : identifiant (gid) de l'onglet — jamais son nom, qui peut changer.
// STATUTS     : valeurs admises dans la colonne Statut (identiques à la liste déroulante du Sheet).
const reglages = {
  MODE: 'reel',
  SHEET_ID: '1RQc4EFb2OWXL-O9EsC1fRFQ_p4amb2oxDZxXZ0gjy9I',
  ONGLET_GID: '1295018267',
  STATUTS: ['En attente', 'Envoyé', 'Abandon', 'Refusé', 'Accepté'],
};
return $input.all().map(item => ({ json: { ...item.json, reglages } }));

// Valide le corps reçu et le convertit en noms de colonnes du Sheet.
// Sortie : un seul item, { ok, erreur, ligne } — jamais zéro item (la réponse au webhook doit toujours partir).
const entree = $input.first().json;
const r = entree.reglages;
const corps = entree.body || {};
const COLONNES = {
  date_ajout: "Date d'ajout",
  statut: 'Statut',
  entreprise: 'Entreprise',
  poste: 'Poste',
  type: 'Type',
  lieu: 'Lieu / télétravail',
  salaire: 'Salaire',
  experience: 'Expérience',
  equipe: 'Équipe en place',
  correspondance: 'Correspondance',
  lien_offre: "Lien de l'offre",
  canal: 'Canal de candidature',
  contact: 'Contact publié',
  lettre: 'Lettre',
  relecture: 'Relecture',
  date_envoi: "Date d'envoi",
  relance: 'Relance prévue',
  notes: 'Notes',
};

const lien = String(corps.lien_offre || '').trim();
if (!lien) {
  return [{ json: { ok: false, erreur: 'lien_offre manquant : il sert de clé pour retrouver la ligne.', mode: r.MODE } }];
}
if (corps.statut !== undefined && !r.STATUTS.includes(corps.statut)) {
  return [{ json: { ok: false, erreur: 'statut inconnu : ' + corps.statut + ' (valeurs admises : ' + r.STATUTS.join(', ') + ').', mode: r.MODE } }];
}

const ligne = {};
for (const [cle, colonne] of Object.entries(COLONNES)) {
  if (corps[cle] !== undefined && corps[cle] !== null) ligne[colonne] = String(corps[cle]);
}
ligne["Lien de l'offre"] = lien;

return [{ json: { ok: true, mode: r.MODE, ligne } }];

// Demande d'exemple pour la recette (Lancement manuel WF2). Adresse réservée (.invalid) : aucun envoi possible.
return [{ json: { body: {
  destinataire: 'recrutement@exemple.invalid',
  entreprise: 'ZZ Test',
  objet: 'Candidature — Poste de test, Bordeaux',
  corps: 'Bonjour, ceci est un brouillon de recette.',
  cv: 'CV-Karim-Bordeau.pdf',
  relance: false,
} } }];

// MODE                : 'simulation' = contrôles et recherche du CV exécutés (lectures), AUCUN brouillon créé.
//                       'reel'       = le brouillon Gmail est créé. Bascule sur décision explicite, après la recette.
// CV_DOSSIER_ID       : dossier Drive « Job Search/CV » (PDF finaux écrits par build-cv.mjs).
// SHEET_ID, ONGLET_GID: Sheet « Suivi des candidatures » (contrôle des lignes au statut Envoyé).
// DOMAINES_GENERIQUES : messageries grand public — jamais de contrôle par domaine sur ces domaines.
// SIGNES_INTERDITS    : typographie qui trahit un texte écrit par une IA (règle de Karim, 2026-09-29) : refusée dans l'objet et le corps. Émojis refusés aussi.
const reglages = {
  MODE: 'reel',
  CV_DOSSIER_ID: '1pz19yJH0wpAJeItTb1nA8OEz6J1F1mkL',
  SHEET_ID: '1RQc4EFb2OWXL-O9EsC1fRFQ_p4amb2oxDZxXZ0gjy9I',
  ONGLET_GID: '1295018267',
  SIGNES_INTERDITS: ['—', '–', '·', '•', '→', '⇒', '…', '’', '‘', '“', '”', '✓', '✔'],
  DOMAINES_GENERIQUES: ['gmail.com', 'googlemail.com', 'outlook.fr', 'outlook.com', 'hotmail.fr', 'hotmail.com', 'live.fr', 'live.com', 'msn.com', 'yahoo.fr', 'yahoo.com', 'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'neuf.fr', 'laposte.net', 'icloud.com', 'me.com', 'proton.me', 'protonmail.com', 'gmx.fr', 'bbox.fr'],
};
return $input.all().map(item => ({ json: { ...item.json, reglages } }));

// Valide la demande et prépare les requêtes Gmail. Sortie : toujours UN item { ok, erreur | demande, requetes }.
const entree = $input.first().json;
const r = entree.reglages;
const c = entree.body || {};
const txt = v => (v === undefined || v === null) ? '' : String(v).trim();
const refus = erreur => [{ json: { ok: false, erreur, mode: r.MODE } }];

// destinataire : une adresse, ou plusieurs séparées par virgule / point-virgule (ex. contact@ + RH) : un seul brouillon, tous en destinataires.
const liste = [...new Set((Array.isArray(c.destinataire) ? c.destinataire.join(',') : txt(c.destinataire)).toLowerCase().split(/[,;\s]+/).filter(Boolean))];
const destinataire = liste.join(', ');
const relance = c.relance === true || c.relance === 'true';
const demande = {
  destinataire,
  destinataires: liste,
  entreprise: txt(c.entreprise),
  objet: txt(c.objet),
  corps: txt(c.corps),
  cv: txt(c.cv),
  lien_offre: txt(c.lien_offre),
  relance,
};
if (!liste.length) return refus('destinataire manquant ou mal formé.');
const malFormee = liste.find(a => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(a));
if (malFormee) return refus('destinataire manquant ou mal formé : ' + malFormee);
for (const champ of ['entreprise', 'objet', 'corps']) {
  if (!demande[champ]) return refus(champ + ' manquant.');
}
// Typographie d'IA : refus net, avec le signe et le champ fautifs (le texte se corrige côté skill, jamais ici).
const estEmoji = ch => { const cp = ch.codePointAt(0); return (cp >= 0x1F300 && cp <= 0x1FAFF) || (cp >= 0x2600 && cp <= 0x27BF); };
for (const champ of ['objet', 'corps']) {
  const fautif = [...demande[champ]].find(ch => r.SIGNES_INTERDITS.includes(ch) || estEmoji(ch));
  if (fautif) return refus('signe interdit dans ' + champ + ' : « ' + fautif + ' » (typographie d’IA : utiliser la ponctuation du clavier).');
}
if (!relance) {
  if (!demande.cv) return refus('cv manquant : nom du PDF dans le dossier Drive Job Search/CV.');
  if (!/^[^'"\/]+\.pdf$/i.test(demande.cv)) return refus('cv invalide : un nom de fichier .pdf, sans guillemet ni chemin.');
}

// Gmail : {a b} = a OU b.
const ou = termes => termes.length === 1 ? termes[0] : '{' + termes.join(' ') + '}';
const domaines = [...new Set(liste.map(a => a.split('@')[1]))].filter(dm => !r.DOMAINES_GENERIQUES.includes(dm));
const parAdresse = 'in:sent ' + ou(liste.map(a => 'to:' + a));
const requetes = {
  adresse: parAdresse,
  domaine: domaines.length ? 'in:sent ' + ou(domaines.map(dm => 'to:' + dm)) : parAdresse,
  controle_domaine: domaines.length > 0,
  domaines,
};
const cv_requete = "name = '" + demande.cv + "' and '" + r.CV_DOSSIER_ID + "' in parents and trashed = false";
return [{ json: { ok: true, mode: r.MODE, demande, requetes, cv_requete } }];

