const reels = noeud => $(noeud).all().map(i => i.json).filter(j => j && j.id);

const adresses = m => {
  const champ = m.to;
  const brut = [];
  if (champ && Array.isArray(champ.value)) champ.value.forEach(x => brut.push(x.address));
  else if (champ && champ.text) brut.push(champ.text);
  else if (typeof champ === 'string') brut.push(champ);
  if (m.headers && m.headers.to) brut.push(m.headers.to);
  return brut.join(',').toLowerCase();
};
