  const a = adresses(m);
  if (d.destinataires.some(x => a.includes(x))) return true;
  return v.requetes.domaines.some(dm => a.includes('@' + dm));
};
const resume = m => ({ date: m.date || '', objet: m.subject || '', lien: 'https://mail.google.com/mail/u/0/#all/' + (m.threadId || m.id), id: m.id, threadId: m.threadId || '' });

