for (const m of [...reels('Gmail – envois au destinataire'), ...reels('Gmail – envois au domaine')]) {
  if (vise(m)) vus.set(m.id, m);
}
const envois = [...vus.values()].sort((a, b) => new Date(b.date) - new Date(a.date));

