const envoyees = lignes.filter(l => l['Statut'] === 'Envoyé' && (
  (d.lien_offre && String(l["Lien de l'offre"] || '').trim() === d.lien_offre) ||
  (norm(l['Entreprise']) && norm(l['Entreprise']) === norm(d.entreprise))
));

const controles = {
  envois_gmail: envois.length,
  controle_domaine: v.requetes.controle_domaine,
  brouillons_existants: brouillons.length,
  lignes_envoye_sheet: envoyees.length,
};
const bloque = (raison, trouve) => [{ json: { bloque: true, raison, trouve, controles } }];

if (brouillons.length) {
  return bloque('un brouillon vers cette adresse existe déjà : le reprendre plutôt que d’en créer un autre.',
    brouillons.map(m => ({ date: m.date || '', objet: m.subject || '', lien: 'https://mail.google.com/mail/u/0/#drafts' })));
}
const dejaEcrit = envois.length > 0 || envoyees.length > 0;
const traces = [
  ...envois.map(resume),
  ...envoyees.map(l => ({ date: l["Date d'envoi"] || '', objet: 'Sheet : ' + l['Entreprise'] + ' — ' + l['Poste'] + ' (Envoyé)', lien: l["Lien de l'offre"] || '' })),
];
if (!d.relance) {
  if (dejaEcrit) return bloque('candidature déjà envoyée à ce destinataire : pas de second envoi identique. Relance ? la demander explicitement.', traces);
  return [{ json: { bloque: false, type: 'candidature', objet: d.objet, threadId: '', controles } }];
}
if (!dejaEcrit) return bloque('relance demandée, mais aucun envoi antérieur trouvé.', []);
const corps = norm(d.corps);
const identique = envois.find(m => norm(m.text).includes(corps));
if (identique) return bloque('corps identique à un mail déjà envoyé le ' + (identique.date || '?') + ' : réécrire la relance.', [resume(identique)]);
const dernier = envois[0];
const objet = dernier ? 'Re: ' + String(dernier.subject || d.objet).replace(/^(re|tr|fwd?)\s*:\s*/i, '') : d.objet;
return [{ json: { bloque: false, type: 'relance', objet, threadId: dernier ? dernier.threadId : '', controles } }];

// Sentinelle : le CV est-il dans le dossier Drive ? Sortie : toujours UN item.
const trouves = $input.all().map(i => i.json).filter(j => j && j.id);
return [{ json: { trouve: trouves.length > 0, fichier_id: trouves.length ? trouves[0].id : '', nom: trouves.length ? trouves[0].name : '' } }];

